package app.fediferry.ai

import java.util.Base64

/**
 * What a model test sends: a 256-pixel picture of a red circle on blue with a
 * small white label, and masks marking that label for each mask style. Under
 * a kilobyte each, so a test costs next to nothing.
 */
internal object ModelTestImages {
    val picture: ByteArray by lazy { decode("") }

    /** The label transparent, the rest opaque. */
    val maskTransparent: ByteArray by lazy { decode("") }

    /** The label white, the rest black. */
    val maskWhite: ByteArray by lazy { decode("") }

    private fun decode(b64: String): ByteArray = Base64.getDecoder().decode(b64)
}
